package cn.xunxu.core;
import static cn.xunxu.core.GraphService.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import cn.xunxu.core.GraphRepository.Graph;
import java.util.function.Function;
import java.util.*;
class GrowthPlacementRulesTest {
 Graph g;GraphService core;AiClient ai;String sid,root,conv;Map<String,Object> parent,child;GrowthPlacementEngine engine;
 @BeforeEach @SuppressWarnings("unchecked") void setup(){
  g=new Graph();var repo=mock(GraphRepository.class);ai=mock(AiClient.class);var json=new ObjectMapper();when(repo.write(any())).thenAnswer(i->((Function<Graph,Object>)i.getArgument(0)).apply(g));when(repo.encode(any())).thenAnswer(i->json.writeValueAsString(i.getArgument(0)));when(repo.decode(anyString())).thenAnswer(i->json.readValue((String)i.getArgument(0),Map.class));core=new GraphService(repo,ai);var sp=obj(core.createSpace(map("title","顺序测试","goal","祖先总结")));sid=s(sp,"id");root=s(sp,"root_id");conv="conversation";g.put("conversations",map("id",conv,"space_id",sid,"anchor_id",root));
  for(int i=1;i<=4;i++){String qa="qa"+i,tid="t"+i;g.put("qas",map("id",qa,"space_id",sid,"conversation_id",conv,"turn_index",i,"question",i<=2?"世界模型研究方向":"JEPA机制及应用","answer","直接研究证据"));g.put("thoughts",map("id",tid,"qa_id",qa,"text","思想"+i,"role","main","original_vector",List.of(0.2,0.8)));g.put("thought_coordinates",map("id","c"+i,"thought_id",tid,"qa_id",qa,"anchor_id",root,"created_at","2026-10-10T00:00:00Z","semantic",true,"method","test","dimension",2,"vector",List.of(1.0,0.0)));}
  parent=core.newNode(g,map("parent_id",root,"title","世界模型","summary","父方向直接总结"),"research_direction_cluster",new ArrayList<>(List.of("t1","t2")));parent.put("research_level","direction");child=core.newNode(g,map("parent_id",root,"title","JEPA","summary","JEPA直接研究"),"semantic_cluster",new ArrayList<>(List.of("t3","t4")));engine=new GrowthPlacementEngine(core,ai);
  when(ai.call(eq("/growth-placements"),any())).thenAnswer(i->{var body=(Map<String,Object>)i.getArgument(1);return map("decisions",objects(body.get("requests")).stream().map(r->eq(obj(r.get("child")).get("node_id"),parent.get("id"))?map("id",r.get("id"),"decision","uncertain","parent_id",null,"reason","早期辅助提及不能倒置总体研究方向"):map("id",r.get("id"),"decision","deepen","parent_id",parent.get("id"),"branch_start_turn",3,"parent_evidence_turns",List.of(1,2),"reason","第1、2轮建立世界模型范围，第3、4轮讨论相关方法，高维语义支持深入关系")).toList());});
 }
 @Test void newNodeUsesChronologyAndSemanticCandidateWithoutChangingAnchor(){engine.place(g,sid,List.of(child));assertEquals(parent.get("id"),child.get("parent_id"));assertEquals(root,g.get("conversations",conv).get("anchor_id"));assertEquals("父方向直接总结",parent.get("summary"));assertEquals(List.of(0.2,0.8),g.get("thoughts","t3").get("original_vector"));assertTrue(g.all("proposals").isEmpty());engine.place(g,sid,List.of());verify(ai,times(1)).call(eq("/growth-placements"),any());}
 @Test void existingNodeOnlyGetsReviewableMoveProposal(){engine.place(g,sid,List.of());assertEquals(root,child.get("parent_id"));assertEquals(1,g.all("proposals").size());var p=g.all("proposals").iterator().next();assertEquals("pending",p.get("status"));assertEquals(parent.get("id"),p.get("target_id"));assertEquals(core.fingerprint(g,sid),p.get("fingerprint"));assertNotNull(p.get("preview"));engine.place(g,sid,List.of());assertEquals(1,g.all("proposals").size());core.approve(s(p,"id"));assertEquals(parent.get("id"),child.get("parent_id"));assertEquals(root,g.get("conversations",conv).get("anchor_id"));assertEquals("父方向直接总结",parent.get("summary"));}
 @Test @SuppressWarnings("unchecked") void switchingTopicDoesNotFollowPreviousNode(){when(ai.call(eq("/growth-placements"),any())).thenAnswer(i->{var body=(Map<String,Object>)i.getArgument(1);return map("decisions",objects(body.get("requests")).stream().map(r->map("id",r.get("id"),"decision","switch","parent_id",null,"reason","明确切换研究问题")).toList());});engine.place(g,sid,List.of(child));assertEquals(root,child.get("parent_id"));assertTrue(g.all("proposals").isEmpty());}
 @Test void frozenParentIsExcluded(){parent.put("frozen",true);engine.place(g,sid,List.of(child));verify(ai,never()).call(eq("/growth-placements"),any());assertEquals(root,child.get("parent_id"));}
 @Test void earlyAuxiliaryEvidenceDoesNotPreventLaterBranchFocus(){g.put("thoughts",map("id","tAux","qa_id","qa1","role","auxiliary","text","顺带提到JEPA"));strings(child,"evidence").add("tAux");engine.place(g,sid,List.of());assertEquals(root,child.get("parent_id"));assertEquals(1,g.all("proposals").size());assertEquals(parent.get("id"),g.all("proposals").iterator().next().get("target_id"));var decision=g.all("relations").stream().filter(r->eq(r.get("source_id"),child.get("id"))).findFirst().orElseThrow();assertEquals(3,decision.get("branch_start_turn"));assertEquals(List.of(1,2),decision.get("parent_evidence_turns"));}
 @Test void stalePreviewIsRetainedAndReplacedAfterReanalysis(){engine.place(g,sid,List.of());var old=g.all("proposals").iterator().next();core.newNode(g,map("parent_id",root,"title","独立新方向","summary","新增结构"),"manual",List.of());engine.place(g,sid,List.of());assertEquals("superseded",old.get("status"));var current=g.all("proposals").stream().filter(p->eq(p.get("status"),"pending")).findFirst().orElseThrow();assertEquals(core.fingerprint(g,sid),current.get("fingerprint"));assertEquals(root,child.get("parent_id"));}
}
